import csv,pathlib,collections
csv.field_size_limit(16000000)
base=pathlib.Path('/workspace/finalisation-donnees-20261027');out=pathlib.Path('/dev/shm/data-automation-20261028/consolidated-30oct')
with (base/'reconciliation-79-ecarts.csv').open(encoding='utf-8-sig',newline='')as f:r=csv.DictReader(f,delimiter=';');names=r.fieldnames;rows=list(r)
new=['fenetre_mensuelle_qualifiee_30oct','nouvelle_fenetre_30oct','investigation_30oct','piece_manquante_usage_30oct','preuve_30oct','ancienne_divergence_resolue_30oct']
for r in rows:
 r.update(fenetre_mensuelle_qualifiee_30oct=r['fenetre_mensuelle_qualifiee_29oct'],nouvelle_fenetre_30oct='False',ancienne_divergence_resolue_30oct=r['ancienne_divergence_resolue_29oct'],piece_manquante_usage_30oct=r['piece_manquante_usage_29oct'],preuve_30oct='Preuves originales conservées ; aucune nouvelle qualification mensuelle de ce cas dans ce lot.',investigation_30oct='Période qualifiée ou refusée conservée, sans nouvelle collecte massive ni altération de sa convention.')
 if r['fenetre_mensuelle_qualifiee_29oct']=='True':continue
 i=r['isin']
 if i=='DE000A0H08P6':r.update(investigation_30oct='Bornes voisines testées. Recomposition cash aux seules bornes communes2018-12-28→2019-12-30 :38,2409679%, contre38,2526984%ajusté et38,2505511%TR. Ces bornes ne sont PAS les bornes du calendrier annuel. Le TR2018-12-31→2019-12-31 reproduit37,8073033%officiel ; NAV31décembre2019 absente. Aucun déplacement de la NAV30→31.',piece_manquante_usage_30oct='NAV indépendante au31décembre2019 et méthode cash/réinvestissement de la part exacte ; facteurs avril/juillet encore non rapprochés. Aucun de ces tests ne lève le refus2019.',preuve_30oct='preuves/reprise-2026-10-30/retail-neighbor-dates-30oct.json | preuves/reprise-2026-10-30/retail-independent-cash-reinvestment-30oct.json')
 elif i=='DE000A27Z304':r.update(investigation_30oct='Nouveau protocole réellement observé du client public DeutscheBörse : identité BTCE/XETR/EUR, réponse courante environ246barres. Requête datée décembre2024 :0barre et isComplete. Le flux courant ne constitue pas un historique2021/2023/2024 ni une NAV.',piece_manquante_usage_30oct='Historique officiel exact de la période '+r['year']+' avec devise, continuité et opérations ; le service de marché public actuellement accessible ne fournit pas les bornes anciennes demandées.',preuve_30oct='preuves/reprise-2026-10-30/bitwise-exchange-dated-request-30oct.json')
 elif i in ['FR0013411998','FR0013412004']:r.update(investigation_30oct='Nouvelle route periodic-report/FRA/20251231 issue du menu documentaire officiel effectivement acquise. Rapport semestriel conservé intégralement. Lignes distributions payées/àpayer sans montant ; cette absence ne prouve pas zéro. PourFR0013411998, NAV finale48,2923 cohérente avec la part couverte mais ISIN seulement dans inventaire des swaps : ne constitue pas une identification suffisante de la classe du tableau.',piece_manquante_usage_30oct='Affectations/distributions exhaustives et identification exacte de la part sur2025, ou méthode officielle de niveaux réinvestis. Ni une case comptable vide ni le motAcc du fonds ne qualifie à lui seul la série.',preuve_30oct='preuves/reprise-2026-10-30/amundi-official-document-menu-30oct.json | preuves/reprise-2026-10-30/amundi-periodic-accounting-30oct.json | preuves/reprise-2026-10-30/'+i+'-official-periodic-20251231-30oct.pdf.gz')
 elif i=='FR0010755611':r.update(investigation_30oct='Menu documentaire officiel inspecté ; nouvelle voie semestrielle20251231 identifiée, mais elle ne couvre pas l’exercice'+r['year']+'. Les routes annuelles historiques testées n’ont pas produit la preuve des distributions requise. Pas de zéro déduit des cases vides.',preuve_30oct='preuves/reprise-2026-10-30/amundi-official-document-menu-30oct.json | preuves/reprise-2026-10-30/amundi-accounting-2026-30oct.json')
 elif i=='IE00B4K6B022':r.update(investigation_30oct='Deux avis officiels FCA préservés :0,2214EUR/1février et1,2623EUR/8août2024 ; date Euronext1août pour le second montant contradictoire. Aucun nouvel avis d’annulation/amendement retrouvé, aucun ajustement ajouté/supprimé.',preuve_30oct='Preuves FCA et contradiction documentaire de#1069 conservées ; aucune nouvelle résolution revendiquée.')
for r in rows:
 r['usage_securise_avant_30oct']=r.get('usage_securise','')
 r['usage_securise']=('Voie mensuelle indépendante qualifiée sur cette fenêtre ; calculateur unique/DCA et comparaison selon les exigences des moteurs. Ne résout pas automatiquement l’ancienne cotation.'if r['fenetre_mensuelle_qualifiee_30oct']=='True'else'Cette fenêtre mensuelle reste refusée ; périodes valides et calendriers annuels indépendants conservés. Pièce exacte dans piece_manquante_usage_30oct.')
new.append('usage_securise_avant_30oct')
assert len(rows)==79 and len({(r['isin'],r['year'])for r in rows})==79
assert collections.Counter(r['fenetre_mensuelle_qualifiee_30oct']for r in rows)=={'True':70,'False':9}
with (out/'reconciliation-79-ecarts.csv').open('w',encoding='utf-8-sig',newline='')as f:w=csv.DictWriter(f,fieldnames=list(dict.fromkeys(names+new)),delimiter=';',lineterminator='\n');w.writeheader();w.writerows(rows)
print('79 original identities preserved,70qualified/9refused;0new monthly windows; old divergences unchanged')
